INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('9c2410a7-f275-46d6-b4d7-0c44a54cedbd', 'kablosuz-anc-kulaklik', 'Kablosuz ANC Kulaklık', 2499, 1999, '["Siyah","Beyaz","Mavi"]', 0, 0, 1, 0.5, '<p>Yüksek ses kaliteli, aktif gürültü engelleyici (ANC) özellikli ve 40 saate varan pil ömrü sunan kablosuz kulaklık. Ergonomik tasarımıyla gün boyu konforlu kullanım sağlar.</p>', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&auto=format&fit=crop&q=80', 1, 1, 1, 1, 0, 0, 0, 150, '5fb6ca4e-2a67-49a7-aded-83bba441dae6', 'e405ba1b-00f9-4d7d-8dfc-ca122a272d29', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('4b75c9da-6e1d-47a1-aca8-9021d21f0f33', 'akilli-gps-saat', 'Akıllı GPS Saat', 4999, NULL, '["Siyah","Gri"]', 0, 0, 1, 0.2, '<p>Adım sayar, dahili GPS, detaylı nabız ölçer ve uyku takibi özellikli, 50 metreye kadar suya dayanıklı yeni nesil akıllı saat. Spor aktivitelerinizi detaylı analiz eder.</p>', 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800&auto=format&fit=crop&q=80', 1, 0, 0, 0, 1, 0, 0, 80, '5fb6ca4e-2a67-49a7-aded-83bba441dae6', 'e405ba1b-00f9-4d7d-8dfc-ca122a272d29', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('a0e2c0ee-e9e4-486a-b1aa-c9f5d8b7b809', 'pamuklu-oversize-t-shirt', 'Pamuklu Oversize T-Shirt', 499, 399, '["Siyah","Beyaz","Gri","Krem"]', 0, 0, 1, 0.3, '<p>%100 organik pamuklu yumuşak kumaştan üretilen, unisex kullanıma uygun, dökümlü ve rahat kesim oversize basic t-shirt. Günlük stilinizin vazgeçilmezi olacak.</p>', 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=800&auto=format&fit=crop&q=80', 1, 0, 1, 1, 0, 0, 0, 300, 'fcee8333-aeb6-4dba-85fc-d5908b56e43f', '5805f1eb-dea3-47a9-9e9d-b1844e8d1878', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('bc5ed586-8815-4afd-9fff-1c2f1dfe260e', 'klasik-deri-cuzdan', 'Klasik Deri Cüzdan', 899, NULL, '["Siyah","Kahverengi"]', 0, 0, 1, 0.15, '<p>Birinci sınıf hakiki deriden el işçiliği ile üretilen, çok sayıda kart bölmesi, şeffaf kimlik alanı ve kağıt para gözü bulunan şık ve zamansız cüzdan tasarımı.</p>', 'https://images.unsplash.com/photo-1627124765135-56c678394236?w=800&auto=format&fit=crop&q=80', 1, 0, 0, 0, 1, 0, 0, 120, 'fcee8333-aeb6-4dba-85fc-d5908b56e43f', '5805f1eb-dea3-47a9-9e9d-b1844e8d1878', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('6771810a-1e8d-4b3f-997b-2ecea09fbbf4', 'seramik-kahve-kupasi-seti', 'Seramik Kahve Kupası Seti', 349, 299, '["Beyaz","Krem","Bej"]', 0, 0, 1, 0.6, '<p>Özel tasarım 2''li seramik kahve kupası seti. Ergonomik kulp tasarımı ve mat dış yüzeyi ile kahve keyfinizi katlar. Bulaşık makinesinde ve mikrodalga fırında kullanılabilir.</p>', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=800&auto=format&fit=crop&q=80', 1, 0, 1, 0, 0, 0, 0, 95, 'cc6675ef-466d-4d6d-a51d-121344fefcb4', '71e872db-0fb3-4384-ae25-6e418c1033d3', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('e368a756-d6ec-4c3b-abb3-e909bf6fb393', 'modern-metal-masa-lambasi', 'Modern Metal Masa Lambası', 1249, 999, '["Siyah","Sarı"]', 0, 0, 1, 1.2, '<p>Mat metal gövdesi ve ayarlanabilir başlığı ile modern ve minimalist çalışma masası lambası. Göz yormayan LED ışık teknolojisiyle verimli bir çalışma ortamı sağlar.</p>', 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=800&auto=format&fit=crop&q=80', 1, 1, 1, 0, 0, 0, 0, 50, 'cc6675ef-466d-4d6d-a51d-121344fefcb4', '71e872db-0fb3-4384-ae25-6e418c1033d3', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('36b41a29-2d6d-4e7b-b5f4-5780593d76fc', 'celik-termos-matara', 'Çelik Termos Matara', 799, NULL, '["Siyah","Antrasit","Mavi"]', 0, 0, 1, 0.4, '<p>Çift duvar vakum yalıtımlı paslanmaz çelik gövdesiyle içeceklerinizi 12 saate kadar sıcak, 24 saate kadar buz gibi soğuk tutan sızdırmaz sporcu matarası.</p>', 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=800&auto=format&fit=crop&q=80', 1, 0, 0, 0, 1, 0, 0, 200, '772fb73b-ca54-467d-af17-81f05de7d6f6', '9065840b-08b8-44f0-b7bc-3acfe5ccb36f', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO urunler (id, slug, ad, fiyat, indirimliFiyat, renkSecenekleri, kartelaIcCephe, kartelaDisCephe, iadeImkaniVar, desi, aciklama, resimUrl, aktif, oneCikan, firsatUrunu, yeniUrun, cokSatanlar, goruntulemeSayisi, satisAdedi, stokAdedi, kategoriId, markaId, olusturulmaTarihi, guncellenmeTarihi) VALUES ('8ee65281-9b6f-4e6a-9dbe-714fe1719403', 'kaymaz-yoga-mati', 'Kaymaz Yoga Matı', 649, 549, '["Pembe","Mor","Mavi"]', 0, 0, 1, 0.95, '<p>6 mm kalınlığında, çevre dostu TPE malzemeden üretilen, yüksek yoğunluklu yapısıyla eklemleri destekleyen ve mükemmel zemin tutuşu sağlayan profesyonel spor ve yoga matı.</p>', 'https://images.unsplash.com/photo-1592432678016-e910b452f9a2?w=800&auto=format&fit=crop&q=80', 1, 1, 1, 1, 0, 0, 0, 110, '772fb73b-ca54-467d-af17-81f05de7d6f6', '9065840b-08b8-44f0-b7bc-3acfe5ccb36f', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
